INSERT INTO content (slug, title, description, body) VALUES
  (
    'index',
    'Butte Bible Fellowship – The Church on Pillsbury Road',
    'A non-denominational local church in Chico, California.',
    $hast${"type":"root","children":[{"type":"element","tagName":"h2","properties":{},"children":[{"type":"text","value":"Welcome to Butte Bible Fellowship"}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"We’re very glad you’ve found our website! We are a non-denominational local church that exists to glorify God by loving Him, living our lives as best we can consistent with what Jesus taught and modeled, and inviting others into biblical community. We’d be pleased if you join us for a few Sundays to get a feel for who we are and who we are becoming."}]},{"type":"element","tagName":"blockquote","properties":{},"children":[{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"“They devoted themselves to the apostles’ teaching and to fellowship … and to prayer.” "},{"type":"element","tagName":"em","properties":{},"children":[{"type":"text","value":"Acts 2:42"}]}]}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"Someone once said that the local church is like a hospital where even the doctors are sick. To be the Church…that’s our desire; a local expression of the new community described in Acts where everyone’s welcome to grow together―finding hope together―in Christ."}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"We are currently a small gathering of seasoned believers who desire to transition into a spiritually healthy multigenerational church that honors valued Christian traditions while living and serving well in 21st century Chico."}]},{"type":"element","tagName":"blockquote","properties":{},"children":[{"type":"element","tagName":"p","properties":{},"children":[{"type":"element","tagName":"strong","properties":{},"children":[{"type":"text","value":"Our intent is to be the Church;"}]}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"element","tagName":"strong","properties":{},"children":[{"type":"text","value":"Imperfect people in biblical community…"}]}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"element","tagName":"strong","properties":{},"children":[{"type":"text","value":"Pursuing the character of Christ,"}]}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"element","tagName":"strong","properties":{},"children":[{"type":"text","value":"Furthering the cause of Christ."}]}]}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"We hope you’ll consider joining us."}]},{"type":"element","tagName":"div","properties":{"dataDirective":"invite-grid"},"children":[{"type":"element","tagName":"div","properties":{"dataDirective":"invite-card"},"children":[{"type":"element","tagName":"h3","properties":{},"children":[{"type":"text","value":"Curious about Christianity?"}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"If you are curious about the claims of Christianity and would like to pursue that curiosity in a safe and welcoming place, you’re invited!"}]}]},{"type":"element","tagName":"div","properties":{"dataDirective":"invite-card"},"children":[{"type":"element","tagName":"h3","properties":{},"children":[{"type":"text","value":"Part of a local church?"}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"If you are currently participating in a local church, we’d encourage you to continue there, helping it become all God intends it to be."}]}]},{"type":"element","tagName":"div","properties":{"dataDirective":"invite-card"},"children":[{"type":"element","tagName":"h3","properties":{},"children":[{"type":"text","value":"New to Chico?"}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"If, however, you’re new to Chico, or perhaps among those left wanting by the trends of recent decades, we’d love to have you join us and help us to grow in spiritually healthy ways."}]}]}]}]}$hast$::jsonb
  ),
  (
    'about-us',
    'About Us – Butte Bible Fellowship',
    'A new community for the cause of Christ.',
    $hast${"type":"root","children":[{"type":"element","tagName":"h1","properties":{},"children":[{"type":"text","value":"Our Vision"}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"Modern wisdom says that the best vision statements are clever, easy-to-remember slogans, and above all…brief. If that’s your cup of tea …"}]},{"type":"element","tagName":"blockquote","properties":{},"children":[{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"Our intent is to be the Church;"}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"Imperfect people in biblical community …"}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"Pursuing the character of Christ,"}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"So that we might further the cause of Christ."}]}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"You might, however, prefer a more complete thought. If "},{"type":"element","tagName":"em","properties":{},"children":[{"type":"text","value":"that’s"}]},{"type":"text","value":" your cup of tea, read on!"}]},{"type":"element","tagName":"h2","properties":{},"children":[{"type":"text","value":"Butte Bible Fellowship, the Church on Pillsbury Road"}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"A new community for the cause of Christ."}]},{"type":"element","tagName":"blockquote","properties":{},"children":[{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"It will cost something to walk slow in the parade of the ages, while excited men of time rush about confusing motion with progress. But it will pay in the long run and the true Christian is not much interested in anything short of that."}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"– A.W. Tozer, June 3, 1950"}]}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"BBF, the Church on Pillsbury Road, is an inclusive biblical community. Heavy on gospel, light on religion, BBF desires to be an uncomplicated effort to live well together in the midst of a thoughtful conversation about God."}]},{"type":"element","tagName":"h2","properties":{},"children":[{"type":"text","value":"Dreams"}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"It’s been said that “spirituality wrongly pursued or understood is a major source of human misery and rebellion against God.” As best we can, we desire to pursue spirituality rightly. Slogans often never make it from memorization, to implementation, to reality. Dreams, too, often remain dreams. They are too often derailed by busyness and clutter and the default mode of living life within the parameters of a cultural norm."}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"Our dream at BBF is to live our lives as participants in a community of Christ followers who desire to "},{"type":"element","tagName":"em","properties":{},"children":[{"type":"text","value":"meno"}]},{"type":"text","value":" — "},{"type":"element","tagName":"em","properties":{},"children":[{"type":"text","value":"to remain or abide in Jesus"}]},{"type":"text","value":". We do not particularly intend to be “old fashioned,” but neither do we pursue "},{"type":"element","tagName":"em","properties":{},"children":[{"type":"text","value":"coolness"}]},{"type":"text","value":" for "},{"type":"element","tagName":"em","properties":{},"children":[{"type":"text","value":"coolness"}]},{"type":"text","value":" sake. Rather, we pursue the cause of Christ as understood on the pages of Scripture, and desire an uncomplicated effort to have a serious conversation about God with both believers in Christ and those who have not yet chosen to follow him."}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"The most important thing in our lives is not what we do, but who we are becoming; that’s what we will take into eternity. Discipleship, then, is the process of becoming who Jesus would be if he were you. The church is not the Church without it. And so, we affirm that the life-long process of Christian transformational discipleship enhances our capacity to live as Jesus lived. That is, with his character and capacity to love. Investing ourselves in God’s Word, we enjoy great freedom in abandoning outcomes to God as we “entrust [our] soul to a faithful Creator in doing what is right.” (1 Peter 4:19)"}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"Our desire is to glorify God in the living of our lives. We trust that the gospel well taught—and well lived—enjoys a natural tendency to attract people to become full-time apprentices of Jesus. We believe theology matters; not for the purpose of intellectual achievement, but for the purpose of knowing the one we worship and follow. And yet, while we thoroughly endorse the pursuit of truth (and therefore reality), we choose to avoid camping on those areas of Christian doctrine that tend to be divisive and non-essential to orthodoxy. We choose rather to express our best understanding of those issues (i.e., program of God, eschatology, sign gifts, etc.) when asked, and to express respect and appreciation for those who hold alternative positions. At BBF we desire our emphasis to be on who we are and who we are becoming in Christ, as opposed to what we know, what we do, or proving our distinctives and “being right.”"}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"It is an immense privilege to be a child and heir of the living God (Romans 8:14-17). We believe our proper and joyful response, then, both individually and corporately, is to make disciples as we go—in the on-going and routine living of our lives (Matthew 28:19a)—and that this is best accomplished by preparing and equipping ourselves for ministry as modeled by Jesus and the apostles in Scripture (Ephesians 4:7-13)."}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"The Church—and its local expression on Pillsbury Road—is the bride of Christ. And at the heart of the Church—and this church—is not primarily human leadership, but rather the character of Jesus marked by love, and grace, and forgiveness, and…"}]},{"type":"element","tagName":"blockquote","properties":{},"children":[{"type":"element","tagName":"ul","properties":{},"children":[{"type":"element","tagName":"li","properties":{},"children":[{"type":"text","value":"a return to the cross"}]},{"type":"element","tagName":"li","properties":{},"children":[{"type":"text","value":"surrender, repentance, and obedience"}]},{"type":"element","tagName":"li","properties":{},"children":[{"type":"text","value":"reconciliation and restoration"}]},{"type":"element","tagName":"li","properties":{},"children":[{"type":"text","value":"discipleship / apprenticeship"}]},{"type":"element","tagName":"li","properties":{},"children":[{"type":"text","value":"truth telling and the expressions of giftedness"}]},{"type":"element","tagName":"li","properties":{},"children":[{"type":"text","value":"humility and sacrifice"}]}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"… and a resurrected Jesus who will one day return."}]}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"We desire that our dreams for spiritual growth and health morph into reality under the direction of the Holy Spirit in response to our prayer, our submission to the power and authority of Jesus Christ, our obedience to biblical teaching as best we know how, and to thoughtful strategic thinking consistent with biblical models and principles. We are followers of Jesus Christ who share a hunger to live our lives as Jesus would live them were he us; to enjoy the abundance Jesus came to offer (John 10:10). We believe that the description of the new community created by the Holy Spirit in Acts 2:41-47 remains the pattern for a healthy Church today. We believe it is possible, under the influence and direction of the Holy Spirit, to establish a similar community of like-minded believers in our 21st century context. With one heart and singleness of purpose, our desire is to experience life together in ways that hold to the core values expressed in Acts 2 and, indeed, throughout Scripture."}]},{"type":"element","tagName":"blockquote","properties":{},"children":[{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"Jesus then came into Galilee announcing the good news from God."}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"‘All the preliminaries have been taken care of,’ he said,"}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"‘and the rule of God is now accessible to everyone. Review your plans for living [repent]"}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"and base your life on this remarkable new opportunity.’"}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"– Mark 1:14-15 (par)"}]}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"As we pursue the cause of Christ, we assume that change is both possible and normal; that Jesus has provided a pattern for Christian spiritual formation as modeled in the way he lived his life."}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"element","tagName":"strong","properties":{},"children":[{"type":"text","value":"Our Vision"}]},{"type":"text","value":", then, is to live our lives intentionally in the kingdom that has come near in the person of Jesus. That was the gospel he preached. He came announcing, manifesting, and teaching the availability and nature of the kingdom of the heavens. “For I was sent for this purpose,” he said (Luke 4:43). If we are faithful to this simple truth, if we do justice to it in full devotion, we will find joy."}]},{"type":"element","tagName":"blockquote","properties":{},"children":[{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"Joy is the fulfillment of that for which we have been created."}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"– Oswald Chambers"}]}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"element","tagName":"strong","properties":{},"children":[{"type":"text","value":"Our Intention"}]},{"type":"text","value":" is to be “kingdom people.” That is, the vision of life in the kingdom through reliance upon Jesus makes it possible for us to intend to live in his kingdom. We can actually decide to do it. Grace is opposed to merit; it is not opposed to effort."}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"element","tagName":"strong","properties":{},"children":[{"type":"text","value":"Our Means"}]},{"type":"text","value":" are readily available. The “how to” of Christian spiritual transformation (Romans 12:2) center around replacing our inner character (which is “lost”) with the inner character of Jesus—his vision, understanding, feelings, decisions, and nature. A curriculum for Christlikeness is found in the gospels where we see how the man Jesus actually lived his life … in devotion to his Father, in prayer, in study, in service, in worship, in deference to others. We are not alone in this pursuit. We have rich resources available to us in the example and teachings of Jesus, in the Scriptures generally, and in his people."}]},{"type":"element","tagName":"h1","properties":{},"children":[{"type":"text","value":"Core Beliefs"}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"We at BBF are evangelical Christians. To be evangelical has always meant, along with a personal devotion to Jesus Christ as Lord and Savior, affirming a cluster of essential doctrines. As evangelical Protestants, we align ourselves with three such affirmations born of the Reformation:"}]},{"type":"element","tagName":"ul","properties":{},"children":[{"type":"element","tagName":"li","properties":{},"children":[{"type":"text","value":"Scripture, not the church and not personal anecdotal experience, is the final authority for Christian faith and practice"}]},{"type":"element","tagName":"li","properties":{},"children":[{"type":"text","value":"Faith in Christ, not in works, is the means to salvation"}]},{"type":"element","tagName":"li","properties":{},"children":[{"type":"text","value":"All believers in Christ, not only clergy, are the Church’s true priesthood."}]}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"Butte Bible Fellowship’s core beliefs express our theological positions on the essentials of Christian faith. Ours is a biblical theology grounded in Old and New Testament teachings rather than a theology that is speculative, subjective, or merely traditional."}]},{"type":"element","tagName":"h2","properties":{},"children":[{"type":"text","value":"Revelation, Scripture, and Authority"}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"We believe that God is revealed in creation, in the Holy Scriptures, and in Jesus Christ, the apex of revelation. The Scriptures (Holy Bible), all sixty-six Old and New Testament books, are divinely authoritative in all they affirm. (Psalm 19:1-6; Hebrews 1:1-2; John 17:17)"}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"We believe in the verbal, plenary inspiration of Scripture. This means the Holy Spirit dynamically/authoritatively superintended (“God-breathed”) the verbal expressions of the human authors of Scripture so that the very thoughts God intended were accurately penned in the wording of the original manuscripts. (2 Timothy 3:16-17; 2 Peter 1:20-21; 1 Corinthians 2:13)"}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"We believe the Scripture is infallibly trustworthy as to truth, and should be interpreted in context and with an appreciation for genre to determine each author’s intended meaning. Our present Bible continues to bear the final authoritative instruction of God for the Church and the world. (John 10:36b; Psalm 19:7; Matthew 5:17-18)"}]},{"type":"element","tagName":"h2","properties":{},"children":[{"type":"text","value":"The Divine Trinity"}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"We believe in God, the one triune, infinite, personal spirit who created and governs all things and who is the sole object of our worship. This one God has always existed in eternal relationship as three persons, Father, Son, and Holy Spirit ― identical and equal in substance (essence), distinct in subsistence (function). The three persons of the Trinity are coeternal in being, coeternal in nature, coequal in power and glory, and having the same attributes and perfection."}]},{"type":"element","tagName":"h3","properties":{},"children":[{"type":"text","value":"God the Father"}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"We believe that God the Father is the holy and loving Creator of all things. Unlimited in time, space, knowledge, and power, the Father intends all that comes to pass. Although distinct from His creation, He is immanently at work in it. (Psalm 139:1-16; 1 Corinthians 8:6; John 5:7)"}]},{"type":"element","tagName":"h3","properties":{},"children":[{"type":"text","value":"God the Son"}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"We believe that the Lord Jesus Christ is the eternal Son of God. He became man, without ceasing to be God, and was conceived by the Holy Spirit and born of the Virgin Mary in order to redeem sinful humanity. He satisfied God’s holy and just demands by dying on the cross as our substitute. He assured our redemption by His resurrection from the dead in the same, though glorified, body in which He was crucified. (John 1:1-2; Luke 1:35; Romans 3:24-25; 1 Peter 1:3-5)"}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"We believe Jesus Christ ascended to heaven and is exalted at the right hand of the Father (i.e., to Him has been given all authority on heaven and on earth [Matthew 28:18]). As High Priest for His people, He serves as our Intercessor and Advocate. (Hebrews 7:25, 9:24; Romans 8:34; 1 John 2:1-2)"}]},{"type":"element","tagName":"h3","properties":{},"children":[{"type":"text","value":"God the Holy Spirit"}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"We believe that the Holy Spirit is the transforming agent who effectively imparts Christ’s new life to all who believe. He convicts men and women in this age as to sin, regenerates the believing and repentant sinner, baptizes them into the body of Christ, dwells within all believers, seals them for the day of redemption, and empowers them in holiness and love to serve God and His Church. (Romans 8:9; 1 Corinthians 12:12-14; Ephesians 1:13-14; Galatians 5:22-25)"}]},{"type":"element","tagName":"h2","properties":{},"children":[{"type":"text","value":"The Creation and Fall of Humanity"}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"In the beginning, God demonstrated His power, wisdom, and goodness by creating the world, everything in it, and everything beyond it. He is a being of unimaginably wonderful power, goodness and love. (Deuteronomy 6:4; Psalm 118:1; Psalm 145:1-9; Matthew 28:19; 2 Corinthians 13:14)"}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"We believe that all human beings are created in the "},{"type":"element","tagName":"em","properties":{},"children":[{"type":"text","value":"imago dei"}]},{"type":"text","value":" (image of God). Through Adam’s disobedience, we by nature become alienated from God, acquire a destructive disposition to sin (imputed sin), and come under the judicial sentence of death. (Genesis 1:25-27; Genesis 3; Romans 3:22-23; 5:12-21; Ephesians 2:1-3, 12)"}]},{"type":"element","tagName":"h2","properties":{},"children":[{"type":"text","value":"Salvation"}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"The central purpose of God’s revelation in Scripture is to call people into reconciled fellowship with Him. We believe God does not intend for sin and suffering to get the last word, nor does He desire that any would perish, but is at work through His Spirit to redeem and reconcile what He has made. (Isaiah 11:6-9; Colossians 1:21-23; 2 Peter 3:9; Revelation 21:1-5)"}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"We believe that salvation (i.e., saved from God’s wrath [1 Thessalonians 1:10]) is the gift of God offered to all humanity by grace and received through personal faith in the Lord Jesus Christ. This faith produces sanctification (see below)."}]},{"type":"element","tagName":"h2","properties":{},"children":[{"type":"text","value":"The Church"}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"All who acknowledge Jesus Christ as Savior and Lord are united with Him as members of His body, the temple of the Holy Spirit, a spiritual community of all believers ―the one true Church."}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"Scripture demands believers to gather for worship, prayer, fellowship and the teaching of the Word; to observe Baptism and Communion as established by Jesus Christ; to offer service to the body through development and use of talents and gifts and outreach to the world."}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"The local expression of the Church is wherever God’s people meet regularly in obedience to this command. Cared for and led by Elders and leaders, church members are to work together in love and unity for the ultimate purpose of glorifying Christ. (Ephesians 1:22-23; 5:25-27; 1 Corinthians 12:12-14)"}]},{"type":"element","tagName":"h2","properties":{},"children":[{"type":"text","value":"Human Destiny"}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"Death seals the eternal destiny of each person. All humanity will experience a bodily resurrection and a judgment that will determine the fate of each individual. God will honor the heart of those who have rejected Him in this life with an eternal, conscious separation. God will honor the heart of those who have embraced His Son in this life with his eternal presence. (Mark 9:43-48; Revelation 20:15; 22:3-5, 11)"}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"In an unannounced moment in time, Christ will come again (the "},{"type":"element","tagName":"em","properties":{},"children":[{"type":"text","value":"Parousia"}]},{"type":"text","value":" … Presence). We believe in the “blessed hope,” the personal, imminent, coming of the Lord Jesus Christ for His redeemed ones (1 Thessalonians 4:13-18) initiating final judgment (Revelation 19) and the establishment of a new heaven and a new earth. (Revelation 21:1)"}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"We therefore live in hope because one day Jesus will return, love and justice will prevail, and God will set the world right. (Matt. 24:30-31; Luke 12:40; Romans 8:37-39; Revelation 21:1-5)"}]},{"type":"element","tagName":"h2","properties":{},"children":[{"type":"text","value":"Sanctification (footnote to Salvation)"}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"element","tagName":"strong","properties":{},"children":[{"type":"text","value":"Positional sanctification"}]},{"type":"text","value":" – "},{"type":"element","tagName":"em","properties":{},"children":[{"type":"text","value":"justification"}]},{"type":"text","value":". The Apostle John tells us that “…to all who did receive him, to those who believed in his name, he gave the right to become children of God…” (John 1:12). Salvation has been made available to those who have chosen to “believe in his name.” At salvation, believers are justified, declared righteous in conformity to the image of Jesus Christ. “For whom He foreknew, He also predestined to become conformed to the image of His Son, that He might be the first-born among many brethren” (Rom. 8:29). This is entirely a work of God."}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"element","tagName":"strong","properties":{},"children":[{"type":"text","value":"Experiential sanctification"}]},{"type":"text","value":" – "},{"type":"element","tagName":"em","properties":{},"children":[{"type":"text","value":"spiritual maturity"}]},{"type":"text","value":". The goal is Christlikeness, the result of the ministry of the Holy Spirit in producing godliness (the character of Christ) in the life of the believer. In essence, progressive sanctification is becoming in experience what we already are positionally in Christ. The Holy Spirit operates in believers to free them experientially from the power of sin and death. “And do not be conformed to this world, but be transformed by the renewing of your mind, that you may prove what the will of God is, that which is good and acceptable and perfect” (Rom. 12:2)."}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"The progress of sanctification, or spiritual maturity, is marked by conflict, spiritual warfare, because our new life in Christ is on a "},{"type":"element","tagName":"em","properties":{},"children":[{"type":"text","value":"collision course"}]},{"type":"text","value":" with the world, is opposed by Satan, and fought by the sinful nature within us. It is the presence of the Holy Spirit that produces the tension or conflict in our life. This conflict in the life of a believer, rather than being proof of sanctification’s absence, is evidence of its work."}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"Progressive sanctification is accomplished by the Holy Spirit as the believer is filled with the Holy Spirit through the life-long practice of confession and repentance. It is an act of God that involves cooperative participation on the part of the believer. “Grace is opposed to merit, but not to effort” (Willard). See 1 Peter 1:13-16, Philippians 2:12-13, Colossians 3 and other texts that call for participation on the part of the believer."}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"element","tagName":"strong","properties":{},"children":[{"type":"text","value":"Ultimate sanctification"}]},{"type":"text","value":" – "},{"type":"element","tagName":"em","properties":{},"children":[{"type":"text","value":"glorification"}]},{"type":"text","value":". The final stage in the salvation process is the ultimate sanctification of the believer—the future glorification of the believer. It is realized at resurrection when the believer will be transformed into the likeness of Christ and presented to the Lord as holy. The indwelling of the Holy Spirit in the life of a believer is both the promise of and the agency for this future glorification, which includes 1) the redemption of the body, 2) an inheritance undefiled and eternal, and 3) deliverance from the future wrath of God."}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"“In Him, you also, after listening to the message of truth, the gospel of your salvation—having also believed, you were sealed in Him with the Holy Spirit of promise, who is given as a pledge of our inheritance, with a view to the redemption of God’s own possession, to the praise of His glory” (Eph. 1:13-14; cf. 1 Cor. 1:22)."}]},{"type":"element","tagName":"blockquote","properties":{},"children":[{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"Justification delivers from the penalty of sin"}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"Sanctification delivers from the power of sin"}]},{"type":"element","tagName":"p","properties":{},"children":[{"type":"text","value":"Glorification delivers from the presence of sin"}]}]}]}$hast$::jsonb
  )
ON CONFLICT (slug) DO NOTHING;
